# AUTOGENERATED by unit-tester skill
"""Tests for Utility.quat — quaternion math (all pure functions)."""
import pytest
import numpy as np
import sys, os

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "../.."))

from Utility.quat import (
    quat_xyzw_to_wxyz,
    quat_wxyz_to_xyzw,
    quat_mul_wxyz,
    quat_inv_wxyz,
    quat_to_axis_angle_wxyz,
    axis_angle_to_quat_wxyz,
)


class TestImports:
    def test_all_callable(self):
        for fn in [quat_xyzw_to_wxyz, quat_wxyz_to_xyzw, quat_mul_wxyz,
                   quat_inv_wxyz, quat_to_axis_angle_wxyz, axis_angle_to_quat_wxyz]:
            assert callable(fn)


class TestQuatConversion:
    def test_xyzw_to_wxyz_identity(self):
        q = np.array([0.0, 0.0, 0.0, 1.0])  # xyzw identity
        result = quat_xyzw_to_wxyz(q)
        np.testing.assert_allclose(result, [1.0, 0.0, 0.0, 0.0], atol=1e-7)

    def test_wxyz_to_xyzw_identity(self):
        q = np.array([1.0, 0.0, 0.0, 0.0])  # wxyz identity
        result = quat_wxyz_to_xyzw(q)
        np.testing.assert_allclose(result, [0.0, 0.0, 0.0, 1.0], atol=1e-7)

    def test_roundtrip(self):
        q_xyzw = np.array([0.1, 0.2, 0.3, 0.9])
        q_xyzw = q_xyzw / np.linalg.norm(q_xyzw)
        q_wxyz = quat_xyzw_to_wxyz(q_xyzw)
        q_back = quat_wxyz_to_xyzw(q_wxyz)
        np.testing.assert_allclose(q_back, q_xyzw, atol=1e-7)


class TestQuatMul:
    def test_identity_mul(self):
        identity = np.array([1.0, 0.0, 0.0, 0.0])
        q = np.array([0.5, 0.5, 0.5, 0.5])
        result = quat_mul_wxyz(identity, q)
        np.testing.assert_allclose(result, q / np.linalg.norm(q), atol=1e-7)

    def test_q_times_inv_is_identity(self):
        q = np.array([0.5, 0.5, 0.5, 0.5])
        q_inv = quat_inv_wxyz(q)
        result = quat_mul_wxyz(q, q_inv)
        np.testing.assert_allclose(result, [1.0, 0.0, 0.0, 0.0], atol=1e-7)


class TestAxisAngle:
    def test_identity_to_axis_angle(self):
        q = np.array([1.0, 0.0, 0.0, 0.0])
        axis, angle = quat_to_axis_angle_wxyz(q)
        assert abs(angle) < 1e-5

    def test_90deg_z_roundtrip(self):
        axis_in = np.array([0.0, 0.0, 1.0])
        angle_in = np.pi / 2
        q = axis_angle_to_quat_wxyz(axis_in, angle_in)
        axis_out, angle_out = quat_to_axis_angle_wxyz(q)
        np.testing.assert_allclose(angle_out, angle_in, atol=1e-7)
        np.testing.assert_allclose(axis_out, axis_in, atol=1e-7)

    @pytest.mark.parametrize("angle", [0.1, np.pi / 4, np.pi, 2 * np.pi - 0.01])
    def test_roundtrip_various_angles(self, angle):
        axis = np.array([1.0, 0.0, 0.0])
        q = axis_angle_to_quat_wxyz(axis, angle)
        assert np.allclose(np.linalg.norm(q), 1.0, atol=1e-7)
